from kong_deck_gateway.certificate_readiness import certificate_is_ready_for_promotion, certificate_readiness_violations


NOW = datetime(2026, 7, 30, tzinfo=timezone.utc)


class GatewayCertificateReadinessGateTests(unittest.TestCase):
    def test_identified_certificate_with_margin_and_host_coverage_passes(self):
        certificate = {"certificate_id": "edge-2026-01", "sha256_fingerprint": "ab:" * 31 + "ab", "expires_at": "2026-12-01T00:00:00Z", "dns_names": ["api.example.com", "admin.example.com"]}
        self.assertTrue(certificate_is_ready_for_promotion(certificate, required_hosts=("api.example.com", "admin.example.com"), now=NOW))

    def test_expiry_fingerprint_and_host_failures_are_reported_together(self):
        certificate = {"certificate_id": "edge", "sha256_fingerprint": "short", "expires_at": "2026-08-01T00:00:00Z", "dns_names": ["api.example.com"]}
        violations = certificate_readiness_violations(certificate, required_hosts=("api.example.com", "admin.example.com"), now=NOW, minimum_validity_days=30)
        self.assertIn("sha256_fingerprint_is_invalid", violations)
        self.assertIn("certificate_validity_margin_is_insufficient", violations)
        self.assertIn("hostname_not_covered:admin.example.com", violations)

    def test_missing_metadata_and_invalid_policy_fail(self):
        violations = certificate_readiness_violations({}, required_hosts=("api.example.com",), now=NOW)
        self.assertIn("certificate_id_is_required", violations)
        self.assertIn("expires_at_must_be_timezone_aware", violations)
        self.assertIn("certificate_dns_names_are_required", violations)
        with self.assertRaises(ValueError):
            certificate_readiness_violations({}, required_hosts=("api.example.com",), now=NOW, minimum_validity_days=-1)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations


_ACTIONS = {"create", "update", "delete"}
_ENTITY_TYPES = {"service", "route", "consumer", "upstream", "plugin"}


def destructive_change_violations(changes: list[dict[str, object]], *, approved_by: str | None = None, change_ticket: str | None = None, backup_reference: str | None = None) -> tuple[str, ...]:
    if not changes:
        return ("at_least_one_deck_change_is_required",)
    violations: list[str] = []
    seen: set[tuple[str, str]] = set()
    has_deletion = False
    for index, change in enumerate(changes):
        entity_type = str(change.get("entity_type", "")).strip().lower()
        entity_name = str(change.get("entity_name", "")).strip()
        action = str(change.get("action", "")).strip().lower()
        if entity_type not in _ENTITY_TYPES:
            violations.append(f"change_{index}:entity_type_is_invalid")
        if not entity_name:
            violations.append(f"change_{index}:entity_name_is_required")
        if action not in _ACTIONS:
            violations.append(f"change_{index}:action_is_invalid")
        key = (entity_type, entity_name)
        if entity_name and key in seen:
            violations.append(f"change_{index}:duplicate_entity_change")
        seen.add(key)
        has_deletion = has_deletion or action == "delete"
    if has_deletion and not str(approved_by or "").strip():
        violations.append("destructive_change_requires_reviewer")
    if has_deletion and not str(change_ticket or "").strip():
        violations.append("destructive_change_requires_ticket")
    if has_deletion and not str(backup_reference or "").strip():
        violations.append("destructive_change_requires_backup_reference")
    return tuple(violations)


def deck_change_plan_is_safe(changes: list[dict[str, object]], **evidence: object) -> bool:
    return not destructive_change_violations(changes, **evidence)

from __future__ import annotations


def upstream_capacity_violations(targets: list[dict[str, object]], *, minimum_healthy_targets: int = 2, minimum_healthy_weight: int = 200, minimum_healthy_zones: int = 2) -> tuple[str, ...]:
    for name, value in (("minimum healthy targets", minimum_healthy_targets), ("minimum healthy weight", minimum_healthy_weight), ("minimum healthy zones", minimum_healthy_zones)):
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise ValueError(f"{name} must be a positive integer")
    if not targets:
        return ("at_least_one_upstream_target_is_required",)
    violations: list[str] = []
    seen_names: set[str] = set()
    healthy_targets = 0
    healthy_weight = 0
    healthy_zones: set[str] = set()
    for index, target in enumerate(targets):
        name = str(target.get("name", "")).strip()
        zone = str(target.get("zone", "")).strip()
        healthy = target.get("healthy")
        weight = target.get("weight")
        if not name:
            violations.append(f"target_{index}:name_is_required")
        elif name in seen_names:
            violations.append(f"target_{index}:name_must_be_unique")
        seen_names.add(name)
        if not zone:
            violations.append(f"target_{index}:zone_is_required")
        if not isinstance(healthy, bool):
            violations.append(f"target_{index}:healthy_must_be_boolean")
        if not isinstance(weight, int) or isinstance(weight, bool) or weight < 0:
            violations.append(f"target_{index}:weight_must_be_a_non_negative_integer")
        if healthy is True and isinstance(weight, int) and not isinstance(weight, bool) and weight >= 0:
            healthy_targets += 1
            healthy_weight += weight
            if zone:
                healthy_zones.add(zone)
    if healthy_targets < minimum_healthy_targets:
        violations.append("healthy_target_count_below_minimum")
    if healthy_weight < minimum_healthy_weight:
        violations.append("healthy_target_weight_below_minimum")
    if len(healthy_zones) < minimum_healthy_zones:
        violations.append("healthy_target_zone_diversity_below_minimum")
    return tuple(violations)


def upstream_has_failover_capacity(targets: list[dict[str, object]], **policy: object) -> bool:
    return not upstream_capacity_violations(targets, **policy)

from __future__ import annotations


_SAFE_METHODS = {"GET", "HEAD", "OPTIONS", "TRACE"}


def retry_safety_violations(routes: list[dict[str, object]], *, maximum_retries: int = 3) -> tuple[str, ...]:
    if not isinstance(maximum_retries, int) or isinstance(maximum_retries, bool) or maximum_retries < 0:
        raise ValueError("maximum retries must be a non-negative integer")
    violations: list[str] = []
    seen: set[str] = set()
    for index, route in enumerate(routes):
        name = str(route.get("name", "")).strip()
        if not name:
            violations.append(f"route_{index}:name_is_required")
        elif name in seen:
            violations.append(f"route_{index}:name_must_be_unique")
        seen.add(name)
        methods = route.get("methods")
        if not isinstance(methods, list) or not methods or any(not isinstance(method, str) or not method.strip() for method in methods):
            violations.append(f"route_{index}:methods_must_be_a_non_empty_list")
            normalized: set[str] = set()
        else:
            normalized = {method.upper() for method in methods}
        retries = route.get("retries")
        if not isinstance(retries, int) or isinstance(retries, bool) or retries < 0:
            violations.append(f"route_{index}:retries_must_be_a_non_negative_integer")
            continue
        if retries > maximum_retries:
            violations.append(f"route_{index}:retries_exceed_maximum")
        if retries > 0 and normalized - _SAFE_METHODS and route.get("idempotency_key_required") is not True:
            violations.append(f"route_{index}:unsafe_method_retries_require_idempotency_key")
    return tuple(violations)


def gateway_retry_policy_is_safe(routes: list[dict[str, object]], **policy: object) -> bool:
    return not retry_safety_violations(routes, **policy)

from __future__ import annotations

from datetime import datetime


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def credential_expiry_violations(credentials: list[dict[str, object]], *, now: datetime, maximum_lifetime_seconds: int = 7776000, minimum_rotation_window_seconds: int = 604800) -> tuple[str, ...]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    if not isinstance(maximum_lifetime_seconds, int) or isinstance(maximum_lifetime_seconds, bool) or maximum_lifetime_seconds <= 0:
        raise ValueError("maximum lifetime must be a positive integer")
    if not isinstance(minimum_rotation_window_seconds, int) or isinstance(minimum_rotation_window_seconds, bool) or minimum_rotation_window_seconds < 0:
        raise ValueError("minimum rotation window must be a non-negative integer")
    violations: list[str] = []
    seen: set[str] = set()
    for position, credential in enumerate(credentials):
        identity = str(credential.get("credential_id", "")).strip()
        if not identity:
            violations.append(f"credential_{position}:identity_is_required")
        elif identity in seen:
            violations.append(f"credential_{position}:identity_must_be_unique")
        seen.add(identity)
        issued = _timestamp(credential.get("issued_at"))
        expires = _timestamp(credential.get("expires_at"))
        if issued is None or expires is None:
            violations.append(f"credential_{position}:timestamps_must_be_timezone_aware")
            continue
        lifetime = (expires - issued).total_seconds()
        if lifetime <= 0 or lifetime > maximum_lifetime_seconds:
            violations.append(f"credential_{position}:lifetime_is_out_of_policy")
        if (expires - now).total_seconds() < minimum_rotation_window_seconds:
            violations.append(f"credential_{position}:rotation_window_is_too_short")
    return tuple(violations)


def consumer_credentials_are_rotation_ready(credentials: list[dict[str, object]], **policy: object) -> bool:
    return not credential_expiry_violations(credentials, **policy)

from __future__ import annotations

import ipaddress


def admin_api_exposure_violations(listeners: list[dict[str, object]]) -> tuple[str, ...]:
    if not listeners:
        return ("at_least_one_admin_api_listener_is_required",)
    violations: list[str] = []
    seen: set[str] = set()
    for position, listener in enumerate(listeners):
        address = str(listener.get("address", "")).strip()
        try:
            ip = ipaddress.ip_address(address)
        except ValueError:
            violations.append(f"listener_{position}:address_must_be_an_ip_literal")
            ip = None
        if address in seen:
            violations.append(f"listener_{position}:address_must_be_unique")
        seen.add(address)
        if ip is not None and not ip.is_loopback:
            if listener.get("tls_enabled") is not True:
                violations.append(f"listener_{position}:remote_listener_requires_tls")
            if listener.get("client_authentication_enabled") is not True:
                violations.append(f"listener_{position}:remote_listener_requires_client_authentication")
            if listener.get("rbac_enabled") is not True:
                violations.append(f"listener_{position}:remote_listener_requires_rbac")
            if listener.get("control_plane_only") is not True:
                violations.append(f"listener_{position}:remote_listener_must_be_control_plane_only")
    return tuple(violations)


def admin_api_exposure_is_safe(listeners: list[dict[str, object]]) -> bool:
    return not admin_api_exposure_violations(listeners)

from __future__ import annotations

import re


_SHA256 = re.compile(r"[0-9a-f]{64}\Z")


def state_snapshot_integrity_violations(snapshot: dict[str, object]) -> tuple[str, ...]:
    violations: list[str] = []
    if not str(snapshot.get("snapshot_id", "")).strip():
        violations.append("snapshot_id_is_required")
    if not str(snapshot.get("kong_version", "")).strip():
        violations.append("kong_version_is_required")
    expected = snapshot.get("expected_sha256")
    stored = snapshot.get("stored_sha256")
    for field, value in (("expected_sha256", expected), ("stored_sha256", stored)):
        if not isinstance(value, str) or not _SHA256.fullmatch(value):
            violations.append(f"{field}_is_invalid")
    if isinstance(expected, str) and isinstance(stored, str) and _SHA256.fullmatch(expected) and _SHA256.fullmatch(stored) and expected != stored:
        violations.append("stored_snapshot_digest_mismatch")
    if snapshot.get("encrypted_at_rest") is not True:
        violations.append("snapshot_must_be_encrypted_at_rest")
    if snapshot.get("restore_verified") is not True:
        violations.append("snapshot_restore_must_be_verified")
    return tuple(violations)


def deck_state_snapshot_is_rollback_ready(snapshot: dict[str, object]) -> bool:
    return not state_snapshot_integrity_violations(snapshot)

import unittest

from kong_deck_gateway.state_snapshot_integrity import deck_state_snapshot_is_rollback_ready, state_snapshot_integrity_violations


DIGEST = "a" * 64


class DeckStateSnapshotIntegrityGateTests(unittest.TestCase):
    def test_encrypted_verified_matching_snapshot_passes(self):
        snapshot = {"snapshot_id": "deck-20260804", "kong_version": "3.9", "expected_sha256": DIGEST, "stored_sha256": DIGEST, "encrypted_at_rest": True, "restore_verified": True}
