from __future__ import annotations


def regex_route_priority_violations(routes: list[dict[str, object]], *, maximum_regex_routes: int = 20) -> tuple[str, ...]:
    if not isinstance(maximum_regex_routes, int) or isinstance(maximum_regex_routes, bool) or maximum_regex_routes < 0:
        raise ValueError("maximum regex routes must be a non-negative integer")
    violations: list[str] = []
    priorities: set[int] = set()
    regex_count = 0
    for route_index, route in enumerate(routes):
        paths = route.get("paths")
        regex_paths = []
        if isinstance(paths, list):
            regex_paths = [(path_index, path) for path_index, path in enumerate(paths) if isinstance(path, str) and path.startswith("~")]
        if not regex_paths:
            continue
        regex_count += len(regex_paths)
        for path_index, path in regex_paths:
            pattern = path[1:]
            if not pattern:
                violations.append(f"route_{route_index}:path_{path_index}:regex_pattern_is_required")
            elif not pattern.startswith("/"):
                violations.append(f"route_{route_index}:path_{path_index}:regex_pattern_must_start_with_slash")
        priority = route.get("regex_priority")
        if not isinstance(priority, int) or isinstance(priority, bool) or priority < 0:
            violations.append(f"route_{route_index}:regex_priority_must_be_a_non_negative_integer")
        elif priority in priorities:
            violations.append(f"route_{route_index}:regex_priority_must_be_unique")
        else:
            priorities.add(priority)
    if regex_count > maximum_regex_routes:
        violations.append("regex_route_count_exceeds_maximum")
    return tuple(violations)


def regex_route_priorities_are_safe(routes: list[dict[str, object]], **policy: object) -> bool:
    return not regex_route_priority_violations(routes, **policy)

from __future__ import annotations

from datetime import datetime
import re


_SHA256 = re.compile(r"[0-9a-f]{64}\Z")
_GIT_REVISION = re.compile(r"[0-9a-f]{40}\Z")


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def gateway_promotion_evidence_violations(evidence: dict[str, object], *, now: datetime, maximum_age_seconds: int = 86400) -> tuple[str, ...]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    if not isinstance(maximum_age_seconds, int) or isinstance(maximum_age_seconds, bool) or maximum_age_seconds <= 0:
        raise ValueError("maximum age must be a positive integer")

    violations: list[str] = []
    desired = evidence.get("desired_state_sha256")
    applied = evidence.get("applied_state_sha256")
    if not isinstance(desired, str) or not _SHA256.fullmatch(desired) or not isinstance(applied, str) or not _SHA256.fullmatch(applied):
        violations.append("state_sha256_values_must_be_valid")
    elif desired != applied:
        violations.append("applied_state_sha256_must_match_reviewed_state")
    revision = evidence.get("source_revision")
    if not isinstance(revision, str) or not _GIT_REVISION.fullmatch(revision):
        violations.append("source_revision_must_be_a_full_git_sha")
    if not isinstance(evidence.get("deck_version"), str) or not evidence["deck_version"].strip():
        violations.append("deck_version_is_required")
    for field in ("diff_reviewed", "sync_succeeded", "post_sync_healthcheck_passed"):
        if evidence.get(field) is not True:
            violations.append(f"{field}_must_be_true")

    started = _timestamp(evidence.get("started_at"))
    completed = _timestamp(evidence.get("completed_at"))
    if started is None:
        violations.append("started_at_must_be_timezone_aware")
    if completed is None:
        violations.append("completed_at_must_be_timezone_aware")
    elif completed > now or (now - completed).total_seconds() > maximum_age_seconds:
        violations.append("promotion_evidence_is_not_fresh")
    if started is not None and completed is not None and completed < started:
        violations.append("completed_at_must_not_precede_started_at")
    return tuple(violations)


def gateway_promotion_evidence_is_complete(evidence: dict[str, object], **policy: object) -> bool:
    return not gateway_promotion_evidence_violations(evidence, **policy)

from __future__ import annotations


def gateway_workspace_contract_violations(resources: list[dict[str, object]], *, environment: str) -> tuple[str, ...]:
    if not isinstance(environment, str) or not environment.strip():
        raise ValueError("environment must be a non-empty string")
    expected_environment = environment.strip().lower()
    if not resources:
        return ("at_least_one_resource_is_required",)

    violations: list[str] = []
    identities: set[tuple[str, str]] = set()
    for index, resource in enumerate(resources):
        if not isinstance(resource, dict):
            violations.append(f"resource_{index}:metadata_is_required")
            continue
        resource_type = str(resource.get("type", "")).strip().lower()
        name = str(resource.get("name", "")).strip()
        if not resource_type:
            violations.append(f"resource_{index}:type_is_required")
        if not name:
            violations.append(f"resource_{index}:name_is_required")
        if resource_type and name:
            identity = (resource_type, name)
            if identity in identities:
                violations.append(f"resource_{index}:type_and_name_must_be_unique")
            identities.add(identity)
        if str(resource.get("workspace", "")).strip().lower() != expected_environment:
            violations.append(f"resource_{index}:workspace_must_match_environment")
        tags = resource.get("tags")
        environment_tags = [str(tag).strip().lower() for tag in tags if isinstance(tag, str) and str(tag).strip().lower().startswith("env:")] if isinstance(tags, list) else []
        if environment_tags != [f"env:{expected_environment}"]:
            violations.append(f"resource_{index}:must_have_one_matching_environment_tag")
    return tuple(violations)


def gateway_workspace_contract_is_satisfied(resources: list[dict[str, object]], **policy: object) -> bool:
    return not gateway_workspace_contract_violations(resources, **policy)

from __future__ import annotations

from urllib.parse import urlparse


_ALLOWED_METHODS = {"GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"}


def route_cors_policy_violations(routes: list[dict[str, object]], *, maximum_preflight_age_seconds: int = 86400) -> tuple[str, ...]:
    if not isinstance(maximum_preflight_age_seconds, int) or isinstance(maximum_preflight_age_seconds, bool) or maximum_preflight_age_seconds < 0:
        raise ValueError("maximum preflight age must be a non-negative integer")
    if not routes:
        return ("at_least_one_route_cors_policy_is_required",)
    violations: list[str] = []
    seen: set[str] = set()
    for position, route in enumerate(routes):
        name = str(route.get("route", "")).strip()
        if not name:
            violations.append(f"route_{position}:name_is_required")
        elif name in seen:
            violations.append(f"route_{position}:name_must_be_unique")
        seen.add(name)
        origins = route.get("origins")
        if not isinstance(origins, list) or not origins or any(not isinstance(value, str) or not value.strip() for value in origins):
            violations.append(f"route_{position}:origins_must_be_non_empty_strings")
            origins = []
        if len(origins) != len(set(origins)):
            violations.append(f"route_{position}:origins_must_be_unique")
        for origin in origins:
            if origin == "*":
                if route.get("allow_credentials") is True:
                    violations.append(f"route_{position}:credentialed_cors_cannot_use_wildcard_origin")
                continue
            parsed = urlparse(origin)
            if parsed.scheme != "https" or not parsed.netloc or parsed.path not in {"", "/"} or parsed.params or parsed.query or parsed.fragment:
                violations.append(f"route_{position}:origin_must_be_an_https_origin")
        methods = route.get("methods")
        if not isinstance(methods, list) or not methods or any(method not in _ALLOWED_METHODS for method in methods):
            violations.append(f"route_{position}:methods_are_invalid")
        elif len(methods) != len(set(methods)):
            violations.append(f"route_{position}:methods_must_be_unique")
        max_age = route.get("preflight_max_age_seconds")
        if not isinstance(max_age, int) or isinstance(max_age, bool) or not 0 <= max_age <= maximum_preflight_age_seconds:
            violations.append(f"route_{position}:preflight_max_age_is_invalid")
    return tuple(violations)


def route_cors_policy_is_safe(routes: list[dict[str, object]], **policy: object) -> bool:
    return not route_cors_policy_violations(routes, **policy)

from __future__ import annotations

from ipaddress import ip_network


def forwarded_header_trust_violations(services: list[dict[str, object]], *, trusted_proxy_cidrs: list[str]) -> tuple[str, ...]:
    if not trusted_proxy_cidrs:
        raise ValueError("at least one trusted proxy CIDR is required")
    normalized: set[str] = set()
    for value in trusted_proxy_cidrs:
        try:
            network = ip_network(value, strict=True)
        except (TypeError, ValueError) as error:
            raise ValueError("trusted proxy CIDRs must be canonical networks") from error
        normalized.add(str(network))
    if len(normalized) != len(trusted_proxy_cidrs):
        raise ValueError("trusted proxy CIDRs must be unique")
    if not services:
        return ("at_least_one_service_header_policy_is_required",)
    violations: list[str] = []
    seen: set[str] = set()
    for position, service in enumerate(services):
        name = str(service.get("service", "")).strip()
        if not name:
            violations.append(f"service_{position}:name_is_required")
        elif name in seen:
            violations.append(f"service_{position}:name_must_be_unique")
        seen.add(name)
        for field in ("strip_incoming_forwarded_headers", "replace_x_forwarded_for", "replace_x_forwarded_proto", "generate_request_id"):
            if service.get(field) is not True:
                violations.append(f"service_{position}:{field}_must_be_enabled")
    return tuple(violations)


def forwarded_header_trust_is_safe(services: list[dict[str, object]], **policy: object) -> bool:
    return not forwarded_header_trust_violations(services, **policy)

from __future__ import annotations


_PROTECTED_HEADERS = {"x-request-id", "x-forwarded-for", "x-forwarded-proto", "authorization"}


def request_transformer_violations(policy: dict[str, object]) -> tuple[str, ...]:
    violations: list[str] = []
    changes = policy.get("header_changes")
    if not isinstance(changes, list):
        return ("header_changes_must_be_a_list",)

    seen: set[str] = set()
    for index, change in enumerate(changes):
        if not isinstance(change, dict):
            violations.append(f"change_{index}:must_be_an_object")
            continue
        name = change.get("name")
        if not isinstance(name, str) or not name.strip():
            violations.append(f"change_{index}:name_is_required")
            continue
        normalized = name.lower()
        if normalized in seen:
            violations.append(f"change_{index}:header_name_must_be_unique")
        seen.add(normalized)
        if change.get("operation") not in {"add", "replace", "remove"}:
            violations.append(f"change_{index}:operation_is_invalid")
        if normalized in _PROTECTED_HEADERS and change.get("operation") in {"replace", "remove"}:
            violations.append(f"change_{index}:protected_header_must_not_be_modified")
    if policy.get("preserve_request_id") is not True:
        violations.append("request_id_preservation_is_required")
    return tuple(violations)


def request_transformer_is_safe(policy: dict[str, object]) -> bool:
    return not request_transformer_violations(policy)

